files.hooks/register.ts:
// herd: one line above the prompt and a /herd pane that say, from any session,
// which shepherd tracks are blocked, in review or stale, which sessions wait on
// the person, and whether unattended `claude -p` runs really finished. It draws
// what `herd snapshot --json` prints; herd does the reading and the judging.
// It follows mods/CLAUDE.md: inert where nothing draws (claude -p, cron, the
// SDK), observe-only (every engine event but its own registered /herd is passed
// on unchanged), no tool.call or tool.check hook, no model call, and every
// process it starts is either a read on its clock or a press of the person's.
import { atom, read, update } from 'claude-code'
import type {
  EngineInterface,
  HerdFaults,
  HerdInboxEntry,
  HerdRun,
  HerdSession,
  HerdSnapshot,
  HerdTab,
  On,
  PluginOptions,
  SessionSendResult,
  Timer,
} from 'claude-code'

import { ackedOf, bandOf, configKeyOf, configOf, fitted, peerToastOf, plural, sharedOf, statusOf, tabOf, toneOf, urgentTab, withHealth } from './herd'
import type { Config } from './herd'
import { acceptEntry, ackRuns, boardUrl, errorText, readInbox, readSnapshot } from './read'
import type { Reader } from './read'
import { paneOf, styleOf } from './view'

const PANE = 'herd'

const NO_FAULTS: HerdFaults = { refresh: null, share: null, command: null }

// `plugin` and `key` stay string literals and each atom sits in a const:
// `claude plugin validate` reads them off the source and holds them to
// types/index.d.ts.
const snapshotAtom = atom({ plugin: 'herd', key: 'snapshot' } as const, null)
const ackedAtom = atom({ plugin: 'herd', key: 'acked' } as const, [])
const tabAtom = atom({ plugin: 'herd', key: 'tab' } as const, 'tracks')
const inboxAtom = atom({ plugin: 'herd', key: 'inbox' } as const, null)
const noticeAtom = atom({ plugin: 'herd', key: 'notice' } as const, null)
const faultsAtom = atom({ plugin: 'herd', key: 'faults' } as const, NO_FAULTS)

/**
 * What Ping sends: a question for the other session's model, nothing it must
 * act on. It starts or joins a turn there; the answer stays in that session's
 * own transcript.
 */
export const PING_TEXT =
  'Status check from the person, sent with the herd pane: say in one line, in your own reply here, what you are doing and what you are waiting for. Do not message the sender back.'

/** A refresh another session stored this recently is shown as it is, not read again. */
const FRESH_SHARE = 0.75

/** The band is a plain Button: `h: ` before its pieces, and the engine's hint beside it when focused. */
const BAND_RESERVED_CELLS = 3 + 2

/** The $.store key every session shares its last read under: `{ config, snapshot }`. */
const SHARED = 'shared'

/**
 * The engine as `session.start` (or `session.attach`) bound it: the timers and
 * the presses reach the engine through this, so read.ts and the refresh below
 * are plain functions over it.
 */
type Host = Reader & {
  storeGet: (key: string) => Promise<unknown>
  storeSet: (key: string, value: unknown) => Promise<void>
  status: (text: string | undefined) => void
  toast: (text: string) => void
  log: (text: string) => void
  send: (sessionId: string, text: string) => Promise<SessionSendResult>
  setSnapshot: (snapshot: HerdSnapshot | null) => Promise<unknown>
  setAcked: (acked: string[]) => Promise<unknown>
  setNotice: (notice: string | null) => Promise<unknown>
  setInbox: (inbox: HerdInboxEntry[] | null) => Promise<unknown>
  setFaults: (faults: HerdFaults) => Promise<unknown>
}

/** The module's own state: what a reload may lose. */
type Live = {
  cfg: Config
  key: string
  isLive: boolean
  /** `/herd` is this mod's: registered in this session. Until then /herd is passed on to whatever owns it. */
  isRegistered: boolean
  host: Host | null
  home: string | null
  selfId: string | null
  timers: Timer[]
  isReading: boolean
  isQueued: boolean
  /** The snapshot last shown, and the acks it was shown with. */
  last: HerdSnapshot | null
  shownAt: number | null
  shownAcked: string | null
  /** Keys this session acked with `herd ack`: shown as acked even by a read that began before the press. */
  ackedHere: string[]
  /** The status line last set: set again only when it changes. */
  status: string | undefined
  /** The faults last put in $.state: written again only when they change. */
  faults: HerdFaults
}

/**
 * Binds a Host from `$`. Declared at the top level of this file, each member
 * spelled `$.noun.method(...)`, so the engine reads what the module calls off
 * its source.
 */
function hostOf($: EngineInterface): Host {
  return {
    now: () => $.clock.now(),
    run: (argv, init) => $.process.run(argv, init),
    storeGet: key => $.store.get(key),
    storeSet: (key, value) => $.store.set(key, value),
    status: text => $.ui.status(text),
    toast: text => $.ui.toast(text),
    log: text => $.ui.log(text, { to: 'debug' }),
    send: (sessionId, text) => $.session.send({ to: { sessionId }, text }),
    setSnapshot: snapshot => update($, snapshotAtom, () => snapshot),
    setAcked: acked => update($, ackedAtom, () => acked),
    setNotice: notice => update($, noticeAtom, () => notice),
    setInbox: inbox => update($, inboxAtom, () => inbox),
    setFaults: faults => update($, faultsAtom, () => faults),
  }
}

/** Puts a snapshot and its acks on screen: the state the band and pane read, and the status line. */
async function show(live: Live, host: Host, snapshot: HerdSnapshot | null): Promise<void> {
  const acked = ackedOf(snapshot, live.ackedHere)
  const ackedKey = JSON.stringify(acked)

  live.last = snapshot
  if (snapshot !== null && live.shownAt !== snapshot.at) {
    await host.setSnapshot(snapshot)
    live.shownAt = snapshot.at
  }
  if (live.shownAcked !== ackedKey) {
    await host.setAcked(acked)
    live.shownAcked = ackedKey
  }

  const status = statusOf(snapshot, new Set(acked))

  if (status !== live.status) {
    host.status(status)
    live.status = status
  }
}

/** Records the mod's own failures where the pane and the band show them; a write only when they change. */
async function setFaults(live: Live, host: Host, change: Partial<HerdFaults>): Promise<void> {
  const next = { ...live.faults, ...change }

  if (JSON.stringify(next) !== JSON.stringify(live.faults)) {
    live.faults = next
    await host.setFaults(next)
  }
}

/**
 * One refresh: adopt what another session stored a moment ago, else run herd
 * again, show it, and store it for them. `force` reads whatever is stored. A
 * store that refuses the write never hides a fresh read.
 */
async function tick(live: Live, force: boolean): Promise<void> {
  const host = live.host

  if (host === null) {
    return
  }
  if (live.isReading) {
    live.isQueued = live.isQueued || force

    return
  }

  live.isReading = true

  try {
    const now = await host.now()
    let shareError: string | null = null
    let stored: HerdSnapshot | null = null

    try {
      stored = sharedOf(await host.storeGet(SHARED), live.key)
    } catch (error) {
      shareError = errorText(error)
    }

    if (!force && stored !== null && now - stored.at < live.cfg.periodMs * FRESH_SHARE) {
      await show(live, host, stored)
    } else {
      const snapshot = await readSnapshot(host, live.cfg, live.home)

      host.log(`herd: read in ${snapshot.tookMs} ms (${snapshot.tracks.length} tracks, ${snapshot.sessions.length} sessions, ${snapshot.runs.length} runs)`)
      await show(live, host, snapshot)

      if (shareError === null) {
        shareError = await host.storeSet(SHARED, { config: live.key, snapshot }).then(
          () => null,
          (error: unknown) => errorText(error),
        )
      }
    }
    if (shareError !== null) {
      host.log(`herd: snapshot not shared: ${shareError}`)
    }
    await setFaults(live, host, { refresh: null, share: shareError })
  } catch (error) {
    // Fail open: the band keeps the last snapshot, marked `herd ?`, and the pane says why.
    host.log(`herd: refresh failed: ${String(error)}`)
    await setFaults(live, host, { refresh: errorText(error) }).catch(() => undefined)
  } finally {
    live.isReading = false

    if (live.isQueued) {
      live.isQueued = false
      void tick(live, true)
    }
  }
}

/** Shows the read another session (or this one before a reload) stored, when it was read with these options. */
async function adoptStored(live: Live, host: Host): Promise<void> {
  await show(live, host, sharedOf(await host.storeGet(SHARED), live.key))
}

/** Marks failures as seen with `herd ack`, for every session and the board, then reads again. Says what it acked. */
async function ack(live: Live, host: Host, runs: readonly HerdRun[]): Promise<string> {
  const keys = runs.map(r => r.key)

  await ackRuns(host, live.cfg, live.home, keys)
  live.ackedHere = [...new Set([...live.ackedHere, ...keys])].slice(-500)
  await show(live, host, live.last)
  void tick(live, true)

  const [only] = runs

  return runs.length === 1 && only !== undefined ? `acked ${only.source} ${only.name}` : `acked ${plural(runs.length, 'failure')}`
}

/** Runs one press's work and puts what it said under the pane, a failure included; never rejects. */
async function noted(host: Host, what: string, work: () => Promise<string>): Promise<void> {
  let said: string

  try {
    said = await work()
  } catch (error) {
    said = `${what} failed: ${errorText(error)}`
    host.log(`herd: ${said}`)
  }
  await host.setNotice(said).catch(() => undefined)
}

/**
 * What the mod does once the session has somewhere to draw. `$` may be passed
 * to a function at the top level of this file, and nowhere else.
 */
async function goLive($: EngineInterface, live: Live): Promise<void> {
  live.isLive = true
  live.host = hostOf($)
  live.home = (await $.env.get('HOME').catch(() => undefined)) ?? null
  live.selfId = await $.session.id().catch(() => null)

  // The last snapshot shows at once; the band may have drawn already, while
  // the mod was inert, and a module variable redraws nothing by itself.
  try {
    await adoptStored(live, live.host)
  } catch (error) {
    $.ui.log(`herd: stored snapshot not read: ${String(error)}`, { to: 'debug' })
  }
  $.ui.invalidate('ui.render')

  for (const timer of live.timers) {
    timer.cancel()
  }
  live.timers = [$.clock.after(0, () => void tick(live, false)), $.clock.every(live.cfg.periodMs, () => void tick(live, false))]

  // Last, and caught: register throws for a taken name (a skill or command the
  // person has called herd), and a hook that throws is skipped whole. /herd
  // then stays theirs (command.run passes it on); the band still opens the
  // pane, and the pane's footer says why /herd is missing.
  try {
    await $.command.register({ name: 'herd', description: 'Open the herd pane: shepherd tracks, sessions and headless runs', immediate: true })
    live.isRegistered = true
    await setFaults(live, live.host, { command: null })
  } catch (error) {
    $.ui.log(`herd: /herd not registered: ${String(error)}`, { to: 'debug' })
    await setFaults(live, live.host, { command: errorText(error) }).catch(() => undefined)
  }
}

export function register(on: On, options: PluginOptions) {
  const cfg = configOf(options)
  // isLive is false until the session has a surface; until then every hook
  // only passes its event on. Module state is enough: a reload runs
  // session.start again.
  const live: Live = {
    cfg,
    key: configKeyOf(cfg),
    isLive: false,
    isRegistered: false,
    host: null,
    home: null,
    selfId: null,
    timers: [],
    isReading: false,
    isQueued: false,
    last: null,
    shownAt: null,
    shownAcked: null,
    ackedHere: [],
    status: undefined,
    faults: NO_FAULTS,
  }

  // A terminal session, a background one (`claude --bg`, agent view: it starts
  // on a terminal surface with nobody looking) and a desktop one go live here.
  on('session.start', async ($, e, next) => {
    if ((await $.session.surfaces()).length === 0) {
      return next(e)
    }

    await goLive($, live)

    return next(e)
  })

  // A session that started with nothing to draw on goes live when a client
  // attaches. The terminal never raises it.
  on('session.attach', async ($, e, next) => {
    if (!live.isLive) {
      await goLive($, live)
    }

    return next(e)
  })

  // /clear, /resume and /branch reset $.state and go on under a new session id,
  // with no session.start: read the id again (so Ping never offers this session
  // to itself) and copy the shared snapshot back from $.store. Reads only, so
  // it may run with nothing attached too.
  on('classic.SessionStart', { source: ['clear', 'resume', 'fork'] }, async ($, e, next) => {
    const result = await next(e)

    if (live.isLive) {
      try {
        live.selfId = await $.session.id().catch(() => live.selfId)
        live.last = sharedOf(await $.store.get(SHARED), live.key) ?? live.last
        live.shownAt = live.last?.at ?? null

        const acked = ackedOf(live.last, live.ackedHere)

        live.shownAcked = JSON.stringify(acked)
        // The next refresh pins the status line again if it still has something to say.
        live.status = undefined
        await update($, snapshotAtom, () => live.last)
        await update($, ackedAtom, () => acked)
        await update($, faultsAtom, () => live.faults)
      } catch (error) {
        $.ui.log(`herd: state not restored after ${e.source}: ${String(error)}`, { to: 'debug' })
      }
      $.ui.invalidate('ui.render')
    }

    return result
  }).catch(($, e, next) => next(e))

  // A message from another session: a toast with its sender and first line,
  // never more. A teammate's mailbox delivery, a message for one of this
  // session's agents and a subagent's hand-back are this session's own work,
  // not news. The text is the sender's; nothing here acts on it.
  on('session.receive', async ($, e, next) => {
    const result = await next(e)
    const origin = e.origin

    if (live.isLive && e.agentId === undefined && (origin.kind === 'peer' || origin.kind === 'peer-send-message') && !('teammate' in origin)) {
      const toast = peerToastOf(origin.kind, e.text)

      if (toast !== null) {
        $.ui.toast(toast)
      }
    }

    return result
  }).catch(($, e, next) => next(e))

  // Answers /herd only when it is this mod's, registered in a live session. A
  // skill or command of the person's called herd (register refused the name),
  // and `claude -p "/herd"` where nothing draws, get the event passed on: an
  // answer without next would run no command at all. A gate, so caught.
  on('command.run', { command: 'herd' }, async ($, e, next) => {
    if (!live.isLive || !live.isRegistered) {
      return next(e)
    }

    const tab = tabOf(e.args)

    if (tab !== null) {
      await update($, tabAtom, () => tab)
    }

    const opened = await $.ui.open({ id: PANE, title: 'Herd', focus: true, closeOnEscape: true })

    return opened.isPlaced ? {} : { text: `The herd pane is waiting: ${opened.reason}` }
  }).catch(($, e, next) => next(e))

  on('ui.render', { component: 'Pane', requestId: 'herd' }, async ($, e) => {
    const { Box, Text, Button } = $.ui.resolve(e)
    const snapshot = await read($, snapshotAtom)
    const acked = new Set(await read($, ackedAtom))
    const host = live.host
    // Every press runs through noted: what it said, or why it failed, goes under the pane.
    const press = (what: string, work: (h: Host) => Promise<string>): void => {
      if (host !== null) {
        void noted(host, what, () => work(host))
      }
    }

    return paneOf(
      { Box, Text, Button },
      {
        snapshot,
        acked,
        tab: await read($, tabAtom),
        inbox: await read($, inboxAtom),
        notice: await read($, noticeAtom),
        faults: await read($, faultsAtom),
        nowMs: await $.clock.now(),
        selfId: live.selfId,
      },
      {
        tab: tab => void update($, tabAtom, () => tab).catch(() => undefined),
        refresh: () => void tick(live, true),
        close: () => void $.ui.close({ id: PANE }).catch(() => undefined),
        ack: run => press('ack', h => ack(live, h, [run])),
        ackAll: () => press('ack', h => ack(live, h, (snapshot?.runs ?? []).filter(r => toneOf(r, acked) === 'fail'))),
        board: () => press('board', h => boardUrl(h, live.cfg, live.home)),
        inbox: () =>
          press('inbox', async h => {
            const got = await readInbox(h, live.cfg, live.home, snapshot?.repos ?? [])

            await h.setInbox(got.entries)

            return got.errors.length === 0 ? `inbox: ${got.entries.length} for you` : `inbox: ${got.errors.join('; ')}`
          }),
        accept: (entry: HerdInboxEntry) =>
          press('accept', async h => {
            const said = await acceptEntry(h, live.cfg, live.home, entry)
            const got = await readInbox(h, live.cfg, live.home, snapshot?.repos ?? [])

            await h.setInbox(got.entries)

            return said
          }),
        ping: (session: HerdSession) => {
          // Checked again at the press: the id moves on /clear, /resume and /branch.
          if (!session.isLive || session.sessionId === live.selfId) {
            return
          }
          press('ping', async h => {
            const sent = await h.send(session.sessionId, PING_TEXT)
            const who = session.name ?? session.sessionId.slice(0, 8)

            h.toast(sent.isDelivered ? `ping delivered to ${who}` : `ping to ${who} not delivered: ${sent.reason}`)

            return sent.isDelivered ? `pinged ${who}: its answer stays in its own transcript` : `ping to ${who}: ${sent.reason}`
          })
        },
      },
    )
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (!live.isLive || !live.cfg.isBandOn || e.props.hasSurvey) {
      return next(e)
    }

    const snapshot = await read($, snapshotAtom)
    const acked = new Set(await read($, ackedAtom))
    const faults = await read($, faultsAtom)
    const band = withHealth(bandOf(snapshot, acked), snapshot, faults.refresh, await $.clock.now(), live.cfg.periodMs)
    const segments = fitted(band, Math.max(20, e.props.bodyColumns - BAND_RESERVED_CELLS))

    if (segments.length === 0) {
      return next(e)
    }

    const { Box, Text, Button } = $.ui.resolve(e)
    const fallback: HerdTab = await read($, tabAtom)
    // What the mods after this one draw stays, under this line.
    const below = await next(e)

    return Box({
      flexDirection: 'column',
      children: [
        Button({
          key: 'herd-open',
          label: 'herd',
          hotkey: 'h',
          plain: true,
          onPress: async () => {
            try {
              await update($, tabAtom, () => urgentTab(snapshot, acked, fallback))
              await $.ui.open({ id: PANE, title: 'Herd', focus: true, closeOnEscape: true })
            } catch (error) {
              $.ui.log(`herd: pane not opened: ${String(error)}`, { to: 'debug' })
            }
          },
          children: segments.map(s => Text({ ...styleOf(s.tone), wrap: 'truncate-end', children: [s.text] })),
        }),
        below,
      ],
    })
  })
}

files.hooks/herd.ts:
// The herd mod's pure half: the options, the snapshot `herd snapshot --json`
// prints (checked before it is drawn), and the words the band, the status line
// and the pane say about it. No `$` and no I/O here: read.ts runs herd, this
// file decides what to show. herd itself judges the tracks, sessions and runs.
import type { HerdRun, HerdSession, HerdSnapshot, HerdSource, HerdTab, HerdTone, HerdTrack } from 'claude-code'

// ------------------------------------------------------------------ helpers

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value)

const numberOf = (value: unknown): number | null =>
  typeof value === 'number' && Number.isFinite(value) ? value : null

export const plural = (n: number, word: string): string => `${n} ${word}${n === 1 ? '' : 's'}`

/** How long ago, in one short word: 40s, 12m, 5h, 3d. */
export function agoOf(thenMs: number, nowMs: number): string {
  const s = Math.max(0, Math.round((nowMs - thenMs) / 1000))

  if (s < 60) {
    return `${s}s`
  }
  if (s < 3600) {
    return `${Math.floor(s / 60)}m`
  }
  if (s < 86_400) {
    return `${Math.floor(s / 3600)}h`
  }

  return `${Math.floor(s / 86_400)}d`
}

const pad2 = (n: number): string => String(n).padStart(2, '0')

/** A log's day as MM-DD, local time. */
export function dayOf(ms: number): string {
  const d = new Date(ms)

  return `${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`
}

/** A log's day and minute as MM-DD HH:MM, local time. */
export function stampOf(ms: number): string {
  const d = new Date(ms)

  return `${dayOf(ms)} ${pad2(d.getHours())}:${pad2(d.getMinutes())}`
}

/** The first non-blank line of a message, cut to `max` characters. */
export function firstLineOf(text: string, max = 100): string {
  const line = (text.split('\n').find(l => l.trim() !== '') ?? '').trim()

  return line.length > max ? `${line.slice(0, max - 1)}…` : line
}

// ------------------------------------------------------------------ options

export type Config = {
  isBandOn: boolean
  /** The herd and shepherd executables: a name looked up on PATH, or a path. */
  herd: string
  shepherd: string
  periodMs: number
  staleHours: number
}

const MIN_PERIOD_S = 15
const DEFAULT_PERIOD_S = 60
const DEFAULT_STALE_H = 24

const optionText = (value: unknown, fallback: string): string => (typeof value === 'string' && value.trim() !== '' ? value.trim() : fallback)

/**
 * The plugin's options as the mod reads them, every one defaulted and bounded.
 * Claude Code refuses to load the mod at all when a number is outside its
 * plugin.json min/max, so the bounds here only hold for callers that skip that
 * check (the tests, a smoke script).
 */
export function configOf(options: Readonly<Record<string, unknown>>): Config {
  const period = numberOf(options.refresh_seconds) ?? DEFAULT_PERIOD_S
  const stale = numberOf(options.stale_hours) ?? DEFAULT_STALE_H

  return {
    isBandOn: options.band !== false,
    herd: optionText(options.herd_bin, 'herd'),
    shepherd: optionText(options.shepherd_bin, 'shepherd'),
    periodMs: Math.max(MIN_PERIOD_S, period) * 1000,
    staleHours: Math.max(1, stale),
  }
}

/**
 * The shape `herd snapshot --json` prints (SNAPSHOT_SCHEMA in herd.py). A
 * snapshot of another schema is not drawn: herd and the mod are out of step.
 */
export const SCHEMA = 3

/** What a snapshot was read with: another session's stored read is adopted only when this matches. */
export function configKeyOf(c: Config): string {
  return JSON.stringify([SCHEMA, c.herd, c.staleHours])
}

/** `~` and `~/...` under HOME; anything else as given. */
export function expandHome(path: string, home: string | null): string {
  if (home === null || (path !== '~' && !path.startsWith('~/'))) {
    return path
  }

  return home.replace(/\/$/, '') + path.slice(1)
}

/** The tab `/herd <word>` names, or null. */
export function tabOf(args: string): HerdTab | null {
  const word = args.trim().toLowerCase()

  return word === 'tracks' || word === 'sessions' || word === 'runs' ? word : null
}

/** Waiting on the person first, then working, idle, finished, and failed or stopped last. */
export function sessionRank(s: HerdSession): number {
  if (s.isBlocked) {
    return 0
  }
  if (s.status === 'busy' || s.state === 'working') {
    return 1
  }
  if (s.isLive) {
    return 2
  }
  if (s.state === 'done') {
    return 3
  }

  return 4
}

// ------------------------------------------------------------------ the band and the status line

export type Segment = { text: string; tone: HerdTone }

/** A failure the person acked reads as a warning: still in the band, gone from the status line. */
export function toneOf(run: HerdRun, acked: ReadonlySet<string>): HerdTone {
  return run.tone === 'fail' && acked.has(run.key) ? 'warn' : run.tone
}

const uniqueLabels = (sources: readonly HerdSource[]): string[] => [...new Set(sources.map(s => s.label))]

/** What the band says, as colored pieces: tracks, sessions waiting, then each run source. */
export function bandOf(snapshot: HerdSnapshot | null, acked: ReadonlySet<string>): Segment[] {
  if (snapshot === null) {
    return [{ text: 'herd: reading…', tone: 'dim' }]
  }

  const out: Segment[] = []
  const sep = (): void => {
    if (out.length > 0) {
      out.push({ text: ' │ ', tone: 'dim' })
    }
  }

  if (snapshot.tracksOn && !snapshot.tracksMissing) {
    sep()

    if (snapshot.tracksError !== null) {
      out.push({ text: 'tracks ?', tone: 'warn' })
    } else {
      const t = snapshot.tracks
      const pieces: Segment[] = [
        { text: `${t.filter(x => x.isBlocked).length} blocked`, tone: 'fail' as const },
        // Tracks, as the other counts: one conflicting pair is two conflicting tracks.
        { text: `${t.filter(x => x.conflicts > 0).length} conflicting`, tone: 'fail' as const },
        { text: `${t.filter(x => x.checks === 'failing').length} failing`, tone: 'fail' as const },
        { text: `${t.filter(x => x.status === 'merged').length} merged`, tone: 'warn' as const },
        { text: `${t.filter(x => x.status === 'review').length} in review`, tone: 'busy' as const },
        { text: `${t.filter(x => x.isStale).length} stale`, tone: 'warn' as const },
      ].filter(p => !p.text.startsWith('0 '))

      out.push({ text: plural(t.length, 'track') + (pieces.length > 0 ? ': ' : ''), tone: 'dim' })
      pieces.forEach((p, i) => {
        if (i > 0) {
          out.push({ text: ' · ', tone: 'dim' })
        }
        out.push(p)
      })
    }
  }

  if (snapshot.sessionsOn && !snapshot.sessionsMissing) {
    if (snapshot.sessionsError !== null) {
      sep()
      out.push({ text: 'sessions ?', tone: 'warn' })
    } else {
      const waiting = snapshot.sessions.filter(s => s.isBlocked).length
      const working = snapshot.sessions.filter(s => s.kind === 'background' && s.state === 'working').length

      if (waiting > 0) {
        sep()
        out.push({ text: `${waiting} waiting on you`, tone: 'fail' })
      }
      if (working > 0) {
        sep()
        out.push({ text: `${working} bg working`, tone: 'busy' })
      }
    }
  }

  for (const source of uniqueLabels(snapshot.sources)) {
    const runs = snapshot.runs.filter(r => r.source === source)
    const errors = snapshot.sources.filter(s => s.label === source && s.error !== null)

    sep()

    if (runs.length === 0) {
      out.push({ text: `${source} ${errors.length > 0 ? '?' : 'none'}`, tone: errors.length > 0 ? 'warn' : 'dim' })
      continue
    }

    const newest = Math.max(...runs.map(r => r.mtimeMs))
    const fails = runs.filter(r => toneOf(r, acked) === 'fail')
    const warns = runs.filter(r => toneOf(r, acked) === 'warn')
    const busy = runs.filter(r => r.tone === 'busy')
    const head = `${source} ${newest > 0 ? dayOf(newest) + ' ' : ''}`
    const [firstFail] = fails
    const [firstWarn] = warns

    if (firstFail !== undefined) {
      out.push({ text: `${head}✗ ${fails.length === 1 ? firstFail.verdict : plural(fails.length, 'failure')}`, tone: 'fail' })
    } else if (busy.length > 0) {
      out.push({ text: `${head}${busy.length} running`, tone: 'busy' })
    } else if (firstWarn !== undefined) {
      out.push({ text: `${head}⚠ ${warns.length === 1 ? firstWarn.verdict : plural(warns.length, 'warning')}`, tone: 'warn' })
    } else {
      out.push({ text: `${head}ok`, tone: 'ok' })
    }
  }

  if (snapshot.sourcesError !== null && snapshot.sources.length === 0) {
    sep()
    out.push({ text: 'runs ?', tone: 'warn' })
  }

  return out
}

/** Snapshots this many refresh periods old are marked in the band: the refreshes have stopped landing. */
const STALE_PERIODS = 3

/**
 * The band with what qualifies it in front: `herd ?` while refreshes fail,
 * `as of 5m ago` once the snapshot is older than a few refresh periods. With
 * nothing read yet and a failing refresh, `herd ?` alone: the pane says why.
 */
export function withHealth(band: readonly Segment[], snapshot: HerdSnapshot | null, refreshFault: string | null, nowMs: number, periodMs: number): Segment[] {
  if (snapshot === null && refreshFault !== null) {
    return [{ text: 'herd ?', tone: 'warn' }]
  }

  const notes: Segment[] = []

  if (refreshFault !== null) {
    notes.push({ text: 'herd ?', tone: 'warn' })
  }
  if (snapshot !== null && nowMs - snapshot.at > STALE_PERIODS * periodMs) {
    notes.push({ text: `as of ${agoOf(snapshot.at, nowMs)} ago`, tone: 'dim' })
  }

  return notes.length === 0 ? [...band] : [...notes.flatMap((n, i) => (i === 0 ? [n] : [{ text: ' ', tone: 'dim' as const }, n])), { text: ' │ ', tone: 'dim' }, ...band]
}

/** The framing line the engine may put above a message from another session. */
const PEER_PREFIX = /^(?:Another Claude session|A peer session) sent a message[^\n]*:[ \t]*\n?/

/** The envelope a delivery's body sits in; a nested one is escaped with a backslash. */
const ENVELOPE = /^<\\?(cross-session-message|agent-message|teammate-message)\b([^>]*)>/

/**
 * What a toast says about a message delivered to this session: its kind, the
 * sender's name when the envelope has one, and the body's first line. Null for
 * a hand-back from one of this session's own agents (an `agent-message`
 * envelope), which is not another session's message.
 */
export function peerToastOf(kind: string, text: string): string | null {
  const body = text.trimStart().replace(PEER_PREFIX, '').trimStart()
  const envelope = ENVELOPE.exec(body)

  if (envelope?.[1] === 'agent-message') {
    return null
  }

  const attributes = envelope?.[2] ?? ''
  // The display name the sender gave, else its address unless that is a socket path.
  const name = /\bfrom-name="([^"]+)"/.exec(attributes)?.[1] ?? /\bfrom="([^"]+)"/.exec(attributes)?.[1]
  const from = name === undefined || name.startsWith('uds:') ? '' : ` from ${firstLineOf(name, 40)}`
  const inner = envelope === null ? body : body.slice(envelope[0].length).replace(/<\\?\/[\w-]+>\s*$/, '')

  return `${kind}${from}: ${firstLineOf(inner, 100) || '(empty)'}`
}

/** Cuts the band to `columns`: whole pieces while they fit, then the next one shortened with an ellipsis. */
export function fitted(segments: readonly Segment[], columns: number): Segment[] {
  const out: Segment[] = []
  let left = Math.max(0, Math.floor(columns))

  for (const s of segments) {
    if (s.text.length <= left) {
      out.push(s)
      left -= s.text.length
      continue
    }
    if (left > 1) {
      out.push({ text: `${s.text.slice(0, left - 1)}…`, tone: s.tone })
    }
    break
  }

  return out
}

/** The tab the band opens: what needs the person most. */
export function urgentTab(snapshot: HerdSnapshot | null, acked: ReadonlySet<string>, fallback: HerdTab): HerdTab {
  if (snapshot === null) {
    return fallback
  }
  if (snapshot.runs.some(r => toneOf(r, acked) === 'fail')) {
    return 'runs'
  }
  if (snapshot.tracks.some(t => t.isBlocked || t.conflicts > 0 || t.checks === 'failing')) {
    return 'tracks'
  }
  if (snapshot.sessions.some(s => s.isBlocked)) {
    return 'sessions'
  }

  return fallback
}

/** The status line: the oldest unacknowledged run failure, and how many more there are; undefined when none. */
export function statusOf(snapshot: HerdSnapshot | null, acked: ReadonlySet<string>): string | undefined {
  const fails = (snapshot?.runs ?? []).filter(r => toneOf(r, acked) === 'fail').sort((a, b) => a.mtimeMs - b.mtimeMs)
  const [f] = fails

  if (f === undefined) {
    return undefined
  }

  const where = f.kind === 'late' ? f.source : `${f.source} ${f.name}${f.mtimeMs > 0 ? ` ${dayOf(f.mtimeMs)}` : ''}`

  return `${where}: ${f.why}${fails.length > 1 ? ` (+${fails.length - 1} more, /herd runs)` : ''}`
}

/** The acks a snapshot carries, and those this session made since it was read: herd keeps them, so a union is never stale. */
export function ackedOf(snapshot: HerdSnapshot | null, ackedHere: readonly string[]): string[] {
  return [...new Set([...(snapshot?.acked ?? []), ...ackedHere])]
}

// ------------------------------------------------------------------ the snapshot's shape

/** A field's kind, as a snapshot is checked: `?` also allows null. */
type Kind = 'string' | 'string?' | 'number' | 'number?' | 'boolean' | 'strings' | 'record?'

const isKind = (value: unknown, kind: Kind): boolean =>
  kind === 'strings'
    ? Array.isArray(value) && value.every(v => typeof v === 'string')
    : kind === 'record?'
      ? value === null || isRecord(value)
      : kind.endsWith('?')
        ? value === null || typeof value === kind.slice(0, -1)
        : typeof value === kind

const hasShape = (value: unknown, shape: Readonly<Record<string, Kind>>): boolean =>
  isRecord(value) && Object.entries(shape).every(([field, kind]) => isKind(value[field], kind))

const listOf = (value: unknown, shape: Readonly<Record<string, Kind>>): boolean => Array.isArray(value) && value.every(v => hasShape(v, shape))

/** Every field the band and the pane read of a snapshot and its rows (types/index.d.ts). */
const SNAPSHOT_SHAPE: Readonly<Record<string, Kind>> = {
  at: 'number',
  tookMs: 'number',
  host: 'string',
  tracksOn: 'boolean',
  tracksError: 'string?',
  tracksMissing: 'boolean',
  sessionsOn: 'boolean',
  sessionsError: 'string?',
  sessionsMissing: 'boolean',
  sourcesFile: 'string?',
  sourcesError: 'string?',
  acked: 'strings',
}
const REPO_SHAPE: Readonly<Record<string, Kind>> = { name: 'string', primary: 'string' }
const TRACK_SHAPE: Readonly<Record<string, Kind>> = {
  repo: 'string',
  name: 'string',
  status: 'string',
  goal: 'string?',
  sessionId: 'string?',
  owner: 'string?',
  isLive: 'boolean',
  reviewId: 'string?',
  reviewState: 'string?',
  checks: 'string?',
  checkedAt: 'number?',
  reviewUrl: 'string?',
  lastActivity: 'number?',
  warnings: 'strings',
  conflicts: 'number',
  isBlocked: 'boolean',
  waitingFor: 'string?',
  isStale: 'boolean',
}
const SESSION_SHAPE: Readonly<Record<string, Kind>> = {
  sessionId: 'string',
  shortId: 'string?',
  name: 'string?',
  kind: 'string',
  state: 'string?',
  status: 'string?',
  waitingFor: 'string?',
  startedAt: 'number?',
  cwd: 'string?',
  isLive: 'boolean',
  isBlocked: 'boolean',
  track: 'string?',
}
const RUN_SHAPE: Readonly<Record<string, Kind>> = {
  key: 'string',
  source: 'string',
  kind: 'string',
  name: 'string',
  path: 'string',
  size: 'number',
  mtimeMs: 'number',
  verdict: 'string',
  tone: 'string',
  why: 'string',
  detail: 'string',
  facts: 'record?',
}
const SOURCE_SHAPE: Readonly<Record<string, Kind>> = { label: 'string', kind: 'string', glob: 'string', error: 'string?', count: 'number' }

/**
 * A snapshot as `herd snapshot --json` prints it (or as another session stored
 * it), or null when it is not one this build draws: another schema, or any
 * field or row of another shape. Null is never drawn.
 */
export function snapshotOf(value: unknown): HerdSnapshot | null {
  if (!isRecord(value) || value.schema !== SCHEMA || !hasShape(value, SNAPSHOT_SHAPE)) {
    return null
  }

  const rows =
    listOf(value.repos, REPO_SHAPE) &&
    listOf(value.tracks, TRACK_SHAPE) &&
    listOf(value.sessions, SESSION_SHAPE) &&
    listOf(value.runs, RUN_SHAPE) &&
    listOf(value.sources, SOURCE_SHAPE)

  return rows ? (value as unknown as HerdSnapshot) : null
}

/** Why a value is not a snapshot this build draws, in one phrase. */
export function notSnapshotWhy(value: unknown): string {
  if (!isRecord(value)) {
    return 'no snapshot'
  }
  if (value.schema !== SCHEMA) {
    return `schema ${String(value.schema)}, not ${SCHEMA}: herd and the mod are out of step (update both from one checkout)`
  }

  return 'a snapshot of another shape'
}

/** A stored read another session shared: what it was read with, and the snapshot. */
export function sharedOf(value: unknown, key: string): HerdSnapshot | null {
  return isRecord(value) && value.config === key ? snapshotOf(value.snapshot) : null
}

// ------------------------------------------------------------------ the pane's lines

/** One track's line in the pane: status, review, owner, the first warning. */
export function trackLineOf(t: HerdTrack, nowMs: number): Segment {
  const review =
    t.reviewId === null
      ? ''
      : ` · #${t.reviewId} ${t.reviewState ?? '?'}${t.checks === null ? '' : ` ${t.checks}`}${t.checkedAt === null ? '' : ` (checked ${agoOf(t.checkedAt, nowMs)} ago)`}`
  const owner = t.isBlocked
    ? ` · waiting on you${t.waitingFor === null ? '' : `: ${t.waitingFor}`}`
    : t.owner === null
      ? ' · unclaimed'
      : ` · ${t.owner}`
  const conflicts = t.conflicts > 0 ? ` · ${plural(t.conflicts, 'conflict')}` : ''
  const warning = t.warnings.find(w => !w.startsWith('owner session ended') && w !== 'unclaimed')
  const tone: HerdTone =
    t.isBlocked || t.conflicts > 0 || t.checks === 'failing'
      ? 'fail'
      : t.isStale || t.status === 'merged'
        ? 'warn'
        : t.status === 'review'
          ? 'busy'
          : t.status === 'paused'
            ? 'dim'
            : 'ok'

  return { text: `${t.name} · ${t.status}${review}${owner}${conflicts}${warning === undefined ? '' : ` · ${warning}`}`, tone }
}

/** One session's line in the pane. */
export function sessionLineOf(s: HerdSession, nowMs: number): Segment {
  const state = s.isBlocked
    ? `waiting on you${s.waitingFor === null ? '' : `: ${s.waitingFor}`}`
    : [s.state, s.status].filter((x): x is string => x !== null).join('/') || 'ended'
  const age = s.startedAt === null ? '' : ` · ${agoOf(s.startedAt, nowMs)}`
  const tone: HerdTone =
    s.isBlocked || s.state === 'failed' ? 'fail' : s.status === 'busy' || s.state === 'working' ? 'busy' : s.isLive ? 'ok' : 'dim'

  return { text: `${s.name ?? s.shortId ?? s.sessionId.slice(0, 8)} · ${s.kind} · ${state}${age}${s.track === null ? '' : ` · ${s.track}`}`, tone }
}

/** One run's line in the pane; `acked` before the reason, where a cut line still shows it. */
export function runLineOf(r: HerdRun, acked: ReadonlySet<string>): Segment {
  const when = r.mtimeMs > 0 ? ` ${stampOf(r.mtimeMs)}` : ''
  const seen = r.tone === 'fail' && acked.has(r.key) ? ' · acked' : ''

  return { text: `${r.kind === 'late' ? 'schedule' : r.name}${when}${seen} · ${r.why}`, tone: toneOf(r, acked) }
}

